import { Clone, Edges, GizmoHelper, GizmoViewport, Grid, OrbitControls, useGLTF } from "@react-three/drei";
import { Canvas as ThreeCanvas, useThree } from "@react-three/fiber";
import {
  applyDesignDiff,
  findDesignInKit,
  flattenDesign,
  planeToMatrix,
  selectBestModel,
  toThreeRotation,
  type Camera,
  type Connection,
  type Design,
  type DesignDiff,
  type Kit,
  type Piece,
  type Plane,
  type File as ComposeFile,
  type Type as ComposeKind,
} from "@semio-tech/compose-js";
import * as React from "react";
